from taf.sw.dcap.rd.services.custom_traces.custom_base import CustomTraceBase
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.models.trace_profile_tracer import TraceProfileTracer
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.models.provided_trace import ProvidedTrace
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CustomLteTraceProfile(CustomTraceBase):
    def __init__(self, requirements, **kwargs):
        self.custom_trace_profile = \
            self._generate_custom_trace_profile(requirements=requirements,
                                                trace_type="ENB",
                                                kwargs=kwargs)

    @staticmethod
    def custom_4g_control_plane_interface(custom_lte_dict, **kwargs):
        enb_custom_profile = "cp_4g"
        control_plane_interface = kwargs.get('control_plane_interface', 'auto')
        monitoring_profiles = kwargs.get('monitoring_profiles', 'lte-full-call-scenarios')
        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_lte_dict[enb_custom_profile].get('tracer_id'),
                type="ENB")],
            params=CustomTraceBase.custom_control_plane_interface(control_plane_interface=control_plane_interface,
                                                                  monitoring_profiles=monitoring_profiles),
            type="ENB",
            name=custom_lte_dict[enb_custom_profile].get('name'),
            id=custom_lte_dict[enb_custom_profile].get('tracer_id')) \
            if enb_custom_profile in custom_lte_dict else []

    def custom_tracers(self, custom_profile, trace_type, **kwargs):
        custom_lte_dict = {'lteTracer_4g': {'name': 'Cell Trace', 'tracer_id': 'lteTracer'},
                           'cp_4g': {'tracer_id': 'controlPlane4g', 'name': 'Control Plane 4G'},
                           'condor4gL2': {'tracer_id': 'condor4gL2', 'name': 'Condor 4G L2'},
                           'condor4gTti': {'tracer_id': 'condor4gTti', 'name': 'Condor 4G TTI'},
                           'condor4gAa': {'tracer_id': 'condor4gAa', 'name': 'Condor 4G A'},
                           'condor4gSyslog': {'tracer_id': 'condor4gSyslog', 'name': 'Condor 5G Syslog'},
                           'pmFiles4g': {'tracer_id': 'pmFiles4g', 'name': 'PmFiles 4G'},
                           'scf4g': {'tracer_id': 'scf4g', 'name': 'SCF 4G'},
                           'l1Iq4g': {'tracer_id': 'l1Iq4g', 'name': 'L1-IQ 4G'}}

        profile_functions = {
            'cp_4g': self.custom_4g_control_plane_interface,
            'controlPlane4g': self.custom_4g_control_plane_interface
        }

        custom_lte_profile_option = []
        if custom_profile in profile_functions:
            custom_lte_profile_option.append(profile_functions[custom_profile](
                custom_lte_dict=custom_lte_dict,
                **kwargs))
        elif custom_profile in custom_lte_dict:
            custom_lte_profile_option.append(TraceProfileTracer(
                provided_traces=[ProvidedTrace(
                    snapshot=False,
                    trace=custom_lte_dict[custom_profile].get('tracer_id'),
                    type=trace_type)],
                params=[], type=trace_type,
                name=custom_lte_dict[custom_profile].get('name'),
                id=custom_lte_dict[custom_profile].get('tracer_id')))
        return custom_lte_profile_option
